//! The documentation site's gate: the site builds, and the reference in
//! it is the reference the boundary describes.
//!
//! The reference pages themselves are generated by `gen ffi` and held
//! equal to the boundary by `check-ffi`, which needs nothing but Rust and
//! so runs on every push. This gate is the other half: that the pages
//! compile as MDX and the site actually renders them. It needs a Node, so
//! it runs by hand and in the `verify` matrix (ADR-0014).
//!
//! A page that fails to build is a page nobody reads, and a doc comment
//! is prose written for Rust: it holds braces and angle brackets that MDX
//! reads as code. That is why this gate exists rather than trusting the
//! emitter's escaping.

use std::path::Path;
use std::process::Command;

use crate::binding::{present, step};
use crate::rel;

const SITE: &str = "site";
const REFERENCE: &str = "site/content/docs/reference";
/// Where the static export writes the site.
const OUT: &str = "site/out";
/// Pages the build must have produced whatever else it did: the home
/// page and the guide, so a build that silently rendered nothing fails.
const BUILT: [&str; 2] = ["site/out/index.html", "site/out/docs/install.html"];

pub(crate) fn check(root: &Path) -> i32 {
    if !present("npm", "--version") {
        eprintln!("no `npm` on this machine; the documentation site's gate needs it");
        return 0;
    }
    let site = root.join(SITE);
    if !site.join("node_modules").is_dir()
        && step(
            Command::new("npm")
                .args(["ci", "--silent", "--no-audit", "--no-fund"])
                .current_dir(&site),
            "",
            "the site's dependencies did not install from its lock file",
        )
        .is_err()
    {
        return 1;
    }
    if step(
        Command::new("npm")
            .args(["run", "--silent", "build"])
            .current_dir(&site),
        "",
        "the site did not build",
    )
    .is_err()
    {
        return 1;
    }

    let mut failures = 0;
    for page in BUILT {
        if !root.join(page).is_file() {
            println!("FAIL  the build produced no {page}");
            failures += 1;
        }
    }
    let mut sources = Vec::new();
    collect_mdx(&root.join(REFERENCE), &mut sources);
    if sources.is_empty() {
        println!("FAIL  {REFERENCE} holds no pages; run `cargo xtask gen ffi`");
        return 1;
    }
    for source in &sources {
        let rendered = root.join(rendered_path(root, source));
        if !rendered.is_file() {
            println!(
                "FAIL  {} was generated but the site did not render it",
                rel(root, source)
            );
            failures += 1;
        }
    }
    if failures == 0 {
        println!(
            "ok    {} builds: {} generated reference page(s), every one rendered",
            rel(root, &site),
            sources.len()
        );
    }
    i32::from(failures != 0)
}

/// Every `.mdx` file under a directory, sorted, so a failure names the
/// same page every run.
fn collect_mdx(dir: &Path, out: &mut Vec<std::path::PathBuf>) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    let mut paths: Vec<std::path::PathBuf> = entries.flatten().map(|e| e.path()).collect();
    paths.sort();
    for path in paths {
        if path.is_dir() {
            collect_mdx(&path, out);
        } else if path.extension().is_some_and(|ext| ext == "mdx") {
            out.push(path);
        }
    }
}

/// Where the static export writes a page.
///
/// A directory's own page is written beside the directory rather than
/// inside it: `reference/index.mdx` becomes `docs/reference.html`, and
/// `reference/positions/ts_positions.mdx` becomes
/// `docs/reference/positions/ts_positions.html`.
fn rendered_path(root: &Path, source: &Path) -> String {
    let inside = source
        .strip_prefix(root.join("site/content"))
        .unwrap_or(source)
        .with_extension("html")
        .to_string_lossy()
        .replace('\\', "/");
    let inside = inside
        .strip_suffix("/index.html")
        .map_or(inside.clone(), |folder| format!("{folder}.html"));
    format!("{OUT}/{inside}")
}
